"use client";
import { useEffect, useState } from "react";
import { Panel } from "@/components/demo/kit";

type Login = { email: string; password: string; pin: string };
const copy = {
  title: "Your login",
  note: "Use these on a second device to sign in as the parent. They are shown only on the device that started the plan.",
  email: "Login",
  password: "Password",
  pin: "PIN",
};

/** Credentials generated by the one-tap plan start (D-41), kept in sessionStorage like the jury ones. */
export function FamilyLoginCard() {
  const [login, setLogin] = useState<Login | null>(null);
  useEffect(() => {
    try {
      const saved = JSON.parse(sessionStorage.getItem("brainee-family-login") ?? "null");
      if (saved?.email && saved?.password && saved?.pin) setLogin(saved);
    } catch {}
  }, []);
  if (!login) return null;
  return (
    <Panel title={copy.title} note={copy.note}>
      <dl data-testid="family-login">
        {(["email", "password", "pin"] as const).map((k) => (
          <div key={k} className="flex flex-wrap gap-3">
            <dt>{copy[k]}</dt>
            <dd className="break-all font-mono" data-testid={`family-login-${k}`}>
              {login[k]}
            </dd>
          </div>
        ))}
      </dl>
    </Panel>
  );
}
